	CONSTRAINT "decor_documents_draft_version_positive" CHECK ("decor_documents"."draft_version" >= 1),
	CONSTRAINT "decor_documents_designation_kind" CHECK ("decor_documents"."designation" is null or "decor_documents"."designation"::text = "decor_documents"."kind"::text),
	CONSTRAINT "decor_documents_designation_published" CHECK ("decor_documents"."designation" is null or "decor_documents"."published_revision_id" is not null),
	CONSTRAINT "decor_documents_designation_live" CHECK ("decor_documents"."designation" is null or "decor_documents"."deleted_at" is null)
