-- Hand-written (drizzle-kit does not model triggers): published revisions are
-- append-only (DECOR-006). Row-level, so TRUNCATE in the test harness is unaffected.
CREATE FUNCTION "decor_revisions_immutable"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'decor_revisions is append-only: % refused', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;--> statement-breakpoint
CREATE TRIGGER "decor_revisions_immutable"
  BEFORE UPDATE OR DELETE ON "decor_revisions"
  FOR EACH ROW EXECUTE FUNCTION "decor_revisions_immutable"();
